'use strict';
const SEASON_UI5={bind,help,cityView,menuView};
let seasonCity5='Praha',seasonWeeks5=4,seasonResult5=null,seasonFingerprint5=null;
TITLES.season='Sezóny, počasí & městské události';
function seasonEventsText5(o){return o.events.map(k=>SEASON_EVENTS5[k].name).join(' · ')||'Bez oznámené události';}
function seasonForecastTable5(f){return `<h3>Provozní výhled · ${esc(f.city)}</h3><div class="table-scroll"><table class="data"><thead><tr><th>Týden</th><th>Příchozí</th><th>Obsloužení</th><th>Ztracení hosté</th><th>Káva města</th><th>Výsledek firmy</th><th>Hotovost firmy</th></tr></thead><tbody>${f.series.map(h=>`<tr><td>${h.week} · ${esc(h.weather)}</td><td>${number(h.arrivals)}</td><td>${number(h.served)}</td><td class="${h.lost?'bad':''}">${number(h.lost)}</td><td>${number(h.used,1)} kg</td><td>${money(h.profit)}</td><td>${money(h.cash)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Výhled odehrál ${f.series.length} týdnů kopie celé firmy se skutečnými zásobami, směnami, menu, událostmi a soupeři. Zisk a hotovost patří celé firmě; návštěvy a káva vybranému městu. Rozehraná hra zůstává v T${state.week}. ${f.over?'Firma v této variantě ukončila činnost před koncem výhledu.':''}</p>`;}
function seasonsView(){const list=seasonCalendar5(seasonCity5,seasonWeeks5),now=list[0],stores=state.stores.filter(s=>loc(s.id).city===seasonCity5),last=state.seasons5.history.at(-1),lastCity=last?.cities.find(o=>o.city===seasonCity5),actual=last?.stores.filter(s=>s.city===seasonCity5)||[];return `<div class="view-toolbar"><p class="intro">Připrav směny, nápoje a kávu podle místního zájmu. Toto je oznámený herní kalendář s modelovým počasím; žádná předpověď ze skutečného světa.</p><div class="fields">${field('Město',`<select id="seasonCity5">${CITIES.map(c=>option(c.name,c.name,seasonCity5)).join('')}</select>`)}${field('Výhled',`<select id="seasonWeeks5">${option(4,'4 týdny',seasonWeeks5)}${option(13,'Čtvrtletí · 13 týdnů',seasonWeeks5)}</select>`)}</div></div><div class="report-overview5">${metric('SEZÓNA MĚSTA',now.season,'Herní rok '+now.year+' · týden '+now.yearWeek)}${metric('POČASÍ TOHOTO TAHU',now.temperature+' °C',now.weather)}${metric('VLASTNÍ KAVÁRNY',stores.length,seasonCity5)}${metric('ZÁKLAD ODBĚRU',number(now.coffee,1)+' kg','Orientační plán města před bufferem')}</div><section class="card"><h2>Oznámené týdny · ${esc(seasonCity5)}</h2><div class="table-scroll"><table class="data season-calendar5"><thead><tr><th>Týden</th><th>Sezóna / počasí</th><th>Městský program</th><th>Kanceláře</th><th>Turisté</th><th>Studenti</th><th>Plán kávy</th></tr></thead><tbody>${list.map(o=>`<tr><td>${o.week}${o.week===state.week?' · příští tah':''}</td><td>${esc(o.season)} · ${o.temperature} °C<small>${esc(o.weather)}</small></td><td>${esc(seasonEventsText5(o))}</td>${['office','tourist','student'].map(k=>`<td>${number(o.factors[k]*100,1)} %</td>`).join('')}<td>${number(o.coffee,1)} kg</td></tr>`).join('')}</tbody></table></div><p class="sub">Procenta jsou místní změny zájmu proti běžnému týdnu skupiny. Přesný mix se mění také cenou, pověstí a zkušeností. Plán kávy vychází ze základu adres, menu a sezóny; neobsahuje B2B, e-shop, výrobní buffer ani omezení skutečné obsluhy.</p><div class="actions"><button class="primary" id="runSeasonForecast5" ${!state.stores.length||state.over?'disabled':''}>Prověřit skutečný provoz · ${seasonWeeks5} týdnů</button><button class="soft" data-goto="supply">Připravit zásoby</button><button class="soft" data-goto="roasters">Upravit výrobu</button></div><div id="seasonForecastResult5">${seasonResult5&&seasonResult5.week===state.week&&seasonResult5.city===seasonCity5&&seasonResult5.weeks===seasonWeeks5&&seasonFingerprint5===JSON.stringify(state)?seasonForecastTable5(seasonResult5):''}</div></section><div class="split" style="margin-top:24px"><section class="card"><h2>Co připravit v kavárnách</h2>${stores.map(s=>`<div class="offer"><h3>${esc(loc(s.id).name)}</h3><p class="sub">${esc(SEGMENTS[loc(s.id).segment].name)} · zájem tohoto tahu ${number(seasonDemandFactor5(s)*100,1)} % základního týdne.</p><p>${now.temperature>=23?'Vyšší podíl cold brew, pokud je v nabídce a máš vybavení.':now.temperature<=7?'Hosté v nabídce více volí horké sezónní nápoje.':'Nabídka má běžný poměr studených a horkých nápojů.'} ${s.last?.lost?'Minule odešlo '+number(s.last.lost)+' hostů; před špičkou prověř obsluhu i zásoby.':''}</p><button class="soft mini" data-season-store5="${s.id}">Přejít na kavárnu a směny</button></div>`).join('')||empty('V tomto městě zatím nemáš kavárnu. Kalendář můžeš využít při plánování expanze.')}<p class="sub">Sezónní vliv působí i na soupeře ve stejném městě. Australská města mají obrácené roční období; tropický a horký profil mají vlastní teploty.</p></section><section class="card"><h2>Poslední skutečný týden</h2>${lastCity?`<p>Týden ${last.week} · ${esc(lastCity.season)}, ${lastCity.temperature} °C, ${esc(lastCity.weather)}</p><p class="sub">${esc(seasonEventsText5(lastCity))}</p>${actual.length?`<div class="table-scroll"><table class="data"><thead><tr><th>Kavárna</th><th>Příchozí</th><th>Obsloužení</th><th>Káva</th></tr></thead><tbody>${actual.map(s=>`<tr><td>${esc(loc(s.id).name)}</td><td>${number(s.arrivals)}</td><td>${number(s.served)}</td><td>${number(s.used,1)} kg</td></tr>`).join('')}</tbody></table></div>`:empty('V tomto týdnu zde tvoje kavárny neměly provoz.')}`:empty('Odehraj první týden pro skutečné výsledky.')}<details><summary>Historie města · posledních 26 týdnů</summary>${state.seasons5.history.map(h=>{const o=h.cities.find(o=>o.city===seasonCity5),ss=h.stores.filter(s=>s.city===seasonCity5);return `<p class="sub"><strong>T${h.week} · ${esc(o.season)}, ${o.temperature} °C, ${esc(o.weather)}</strong><br>${esc(seasonEventsText5(o))} · obsloužení ${number(ss.reduce((n,s)=>n+s.served,0))}, ztracení ${number(ss.reduce((n,s)=>n+s.lost,0))}.</p>`}).join('')||empty('Zatím bez historie.')}</details></section></div>`;}
cityView=function(){const o=citySeason5(city);return `<div class="tutorial"><span><strong>${esc(o.season)} · ${o.temperature} °C · ${esc(o.weather)}</strong> · ${esc(seasonEventsText5(o))}</span><button class="soft mini" data-season-city5="${esc(city)}">Otevřít kalendář</button></div>`+SEASON_UI5.cityView();};
menuView=function(){return `<p class="sub">Poměr nápojů reaguje na modelovou místní teplotu. V teple roste zájem o dostupné cold brew, v zimě o zapnutý sezónní nápoj. Vybavení a dostupné položky stále rozhodují.</p>`+SEASON_UI5.menuView();};
bind=function(){SEASON_UI5.bind();if(el('seasonCity5'))el('seasonCity5').onchange=()=>{seasonCity5=el('seasonCity5').value;seasonResult5=null;render()};if(el('seasonWeeks5'))el('seasonWeeks5').onchange=()=>{seasonWeeks5=Number(el('seasonWeeks5').value);seasonResult5=null;render()};if(el('runSeasonForecast5'))el('runSeasonForecast5').onclick=()=>{try{seasonResult5=seasonForecast5(seasonCity5,seasonWeeks5);seasonFingerprint5=JSON.stringify(state);render()}catch(e){toast(e.message)}};on('[data-season-city5]',b=>{seasonCity5=b.dataset.seasonCity5;seasonResult5=null;goto('season')});on('[data-season-store5]',b=>{filterCity=loc(b.dataset.seasonStore5).city;goto('stores')});};
help=function(){SEASON_UI5.help();const p=document.createElement('p');p.textContent='Edice 05.11: Sezóny & události ukazují oznámený herní kalendář každého města na čtyři nebo třináct týdnů. Sezóny, festivaly, veletrhy, semestr a dovolené mění místní zájem různých skupin. Počasí a teplota ovlivňují zájem a poměr dostupných nápojů; Austrálie má obrácené sezóny. Výhled skutečného provozu odehraje kopii celé firmy a nic nemění. Automatické pražení bere místní sezónu do plánu; limit, kapacita a rezerva stále platí. Historie uchovává 26 skutečných týdnů a nevyplňuje zpětně starší hry.';el('modalContent').append(p)};el('help').onclick=help;render();
